    var DICTS = { ru: ru, es: es };
    var SCRIPTS = { ru: ruScript, es: esScript };
    var KEY = 'fb.lang';

    var choice = 'auto';
    try { choice = window.localStorage.getItem(KEY) || 'auto'; } catch (e) { /* default */ }
    var tv = String((window.navigator && (window.navigator.language || window.navigator.userLanguage)) || 'en').slice(0, 2).toLowerCase();
    var lang = choice === 'auto' ? (DICTS[tv] ? tv : 'en') : choice;
    if (lang !== 'en' && !DICTS[lang]) { lang = 'en'; }
    var dict = DICTS[lang] || {};

    function fill(t, v) {
        return v ? t.replace(/\{(\w+)\}/g, function (m, k) { return k in v ? v[k] : m; }) : t;
    }
    function T(text, vars) {
        return fill(Object.prototype.hasOwnProperty.call(dict, text) ? dict[text] : text, vars);
    }

    // The script's output, translated line by line; English where nothing matches
    function TS(text) {
        var pats = SCRIPTS[lang];
        if (!pats || typeof text !== 'string') { return text; }
        return text.split('\n').map(function (line) {
            for (var i = 0; i < pats.length; i++) { line = line.replace(pats[i][0], pats[i][1]); }
            return line;
        }).join('\n');
    }

    function translatePage(root) {
        if (lang === 'en') { return; }
        var walker = document.createTreeWalker(root, 4 /* text */, null, false);
        var n;
        while ((n = walker.nextNode())) {
            var t = n.nodeValue.replace(/^\s+|\s+$/g, '');
            if (t && Object.prototype.hasOwnProperty.call(dict, t)) {
                n.nodeValue = n.nodeValue.replace(t, dict[t]);
            }
        }
        document.documentElement.lang = lang;
    }

    function order() { return ['auto', 'en'].concat(Object.keys(DICTS)); }
    function next() {
        var o = order(), i = o.indexOf(choice);
        var n = o[(i + 1) % o.length];
        try { window.localStorage.setItem(KEY, n); } catch (e) { return false; }
        return true;
    }
    function label() {
        return choice === 'auto' ? T('Auto ({lang})', { lang: NAMES[lang] }) : NAMES[choice];
    }

    window.FB_I18N = { T: T, TS: TS, scripts: SCRIPTS, lang: lang, choice: choice, translatePage: translatePage, next: next, label: label, dicts: DICTS, names: NAMES };
